const mapDependencies={'site-notes':['navigation','site'],navigation:['login','drawer'],meteor:['login'],site:['drawer']};
function renderMap(){
 const agents=scopeAgents(),a=agents.find(a=>a.id===S().map)||agents[0];
 if(a)S().map=a.id;
 const deps=S().dependencies?(mapDependencies[a?.id]||[]):[];
 const lanes=[{name:['探索与准备','Explore & prepare'],ids:['login','cleanup','lab-login']},{name:['实现与验证','Build & validate'],ids:['drawer','meteor','site']},{name:['验收与交付','Review & deliver'],ids:['navigation','site-notes']}];
 return frame(2,`<section class="map-layout"><div class="map-space"><div class="map-top"><div><span class="overline">MISSION / 01</span><h2>${tr('让桌面预览，走到可验收。','Take the desktop preview to review.')}</h2><p>${tr('示例依赖图 · 点击节点，看谁在等待谁','Sample dependencies · Select a node to reveal the handoff')}</p></div>${avatarStack(agents)}</div><div class="mission-root">${orb}<div><small>${tr('共同目标','SHARED OBJECTIVE')}</small><strong>${tr('体验稳定 · 交付可验证','Stable experience · Verifiable delivery')}</strong></div><span>${agents.filter(a=>a.status==='done').length}/${agents.length} ${tr('已交付','delivered')}</span></div><div class="branch-spine"><span></span><span></span><span></span></div><div class="map-lanes">${lanes.map((lane,i)=>`<section class="map-lane"><header><b>0${i+1}</b><h3>${l(lane.name)}</h3>${icon('arrow')}</header>${lane.ids.map(id=>agents.find(a=>a.id===id)).filter(Boolean).map(node=>`<button class="map-node ${node.id===a?.id?'selected':''} ${deps.includes(node.id)?'dependency':''}" data-map-node="${node.id}" aria-pressed="${node.id===a?.id}"><div>${av(node)}<strong>${node.agent}</strong>${status(node)}</div><h3>${esc(l(node.title))}</h3><p>${esc(l(node.summary))}</p><footer><span>${projects[node.project].name}</span><span>${node.progress}/${node.total}</span></footer>${deps.includes(node.id)?`<label>${tr('当前依赖','Dependency')}</label>`:''}</button>`).join('')}</section>`).join('')}</div><div class="map-key"><span><i></i>${tr('当前节点','Selected node')}</span><span><i></i>${tr('等待的上游','Required upstream')}</span><small>${tr('执行状态来自各卡片，连线用于解释协作关系','Card states track execution; connections explain collaboration')}</small></div></div><aside class="map-inspector">${a?`<div class="inspector-person">${av(a)}<div><h3>${a.agent}</h3><span>${spaceName(a.space)} / ${projects[a.project].name}</span></div></div><h2>${esc(l(a.title))}</h2>${status(a)}<p class="inspector-summary">${esc(l(a.answer))}</p><div class="dependency-box"><span>${tr('为什么在这里停住？','What is this waiting for?')}</span><p>${(mapDependencies[a.id]||[]).map(id=>byId(id).agent).join(' + ')||tr('没有上游依赖，可独立推进','No upstream dependency')}</p>${button('dependencies',S().dependencies?tr('收起依赖','Hide dependencies'):tr('显示上游依赖','Show dependencies'),'link','button', 'data-testid="show-dependencies"')}</div><div class="inspector-actions">${button('help',tr('请另一位 Agent 协助','Ask another agent to help'),'people','button primary','data-testid="request-help"')}<button class="button" data-chat="${a.id}">${t('chat')}${icon('chat')}</button><button class="text-button" data-locate="${a.id}">${t('locate')}${icon('out')}</button></div><div class="map-note">${orb}<p>${tr('Norma 负责把上下文交接清楚。每位 Agent 仍在自己的原卡片里执行。','Norma carries context across. Every agent still executes in its original card.')}</p></div>`:`<div class="empty">${t('empty')}</div>`}</aside></section>`);
}
